package com.github.ldavid432.contextualcursor;

import static com.github.ldavid432.contextualcursor.ContextualCursorUtil.mouseInsideBounds;
import com.github.ldavid432.contextualcursor.cache.ImageCache;
import com.github.ldavid432.contextualcursor.config.CursorBackgroundMode;
import com.github.ldavid432.contextualcursor.config.CursorTheme;
import com.github.ldavid432.contextualcursor.provider.EmptyProviderCallbacks;
import com.github.ldavid432.contextualcursor.provider.ProviderCallbacks;
import com.github.ldavid432.contextualcursor.sprite.Sprite;
import java.awt.image.BufferedImage;
import java.util.concurrent.ExecutionException;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import lombok.experimental.Delegate;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.PluginManager;

/**
 * Caches config values as well as sprite images
 */
@Setter
@Getter
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ContextualCursorCache implements ProviderCallbacks
{
	private final Client client;
	private final ContextualCursorConfig config;
	private final PluginManager pluginManager;
	private final ConfigManager configManager;
	private final ItemManager itemManager;
	private final SpriteManager spriteManager;

	public void init()
	{
		cursorScale = (double) config.getCursorScale() / 100;
		itemScale = (double) config.getItemScale() / 100;
		isCursorSmoothScalingEnabled = config.isCursorSmoothScalingEnabled();
		isItemSmoothScalingEnabled = config.isItemSmoothScalingEnabled();
		isCustomDefaultCursorEnabled = config.isCustomDefaultCursorEnabled();
		isDefaultCursorOverlayEnabled = config.isDefaultCursorOverlayEnabled();
		isPersistSpells = config.shouldPersistSpells();
		isPersistItems = config.shouldPersistItems();
		isShowUseItemCursorEnabled = config.isShowUseItemCursorEnabled();
		isDebugTooltipEnabled = config.isDebugTooltipEnabled();
		cursorTheme = config.getCursorTheme();
		cursorBackgroundMode = config.getCursorBackgroundMode();
		isCustomCursorPluginEnabled = configManager.getConfiguration("runelite", "customcursorplugin", Boolean.class) == Boolean.TRUE;
		isLoggedOut = client.getGameState() != GameState.LOGGED_IN;
		isCursorInBounds = mouseInsideBounds(client.getMouseCanvasPosition(), client);
		altPressed = false;
		if (spriteCache == null)
		{
			spriteCache = new ImageCache(this, client, itemManager, spriteManager);
		}
	}

	// config values
	private double cursorScale;
	private double itemScale;
	private boolean isCursorSmoothScalingEnabled;
	private boolean isItemSmoothScalingEnabled;
	private boolean isCustomDefaultCursorEnabled;
	private boolean isDefaultCursorOverlayEnabled;
	private boolean isPersistSpells;
	private boolean isPersistItems;
	private boolean isShowUseItemCursorEnabled;
	private boolean isDebugTooltipEnabled;
	private CursorTheme cursorTheme;
	private CursorBackgroundMode cursorBackgroundMode;

	// non-config values
	private boolean isCustomCursorPluginEnabled;
	private boolean isLoggedOut;
	private boolean isCursorInBounds;
	private boolean altPressed;

	private ImageCache spriteCache;

	@Delegate
	private final ProviderCallbacks callbacks = new EmptyProviderCallbacks()
	{
		@Override
		public void onScaleSmoothingChange(boolean cursorSmoothing, boolean itemSmoothing)
		{
			clear();
		}

		@Override
		public void onScaleChange(double cursorScale, double itemScale)
		{
			clear();
		}

		@Override
		public void onThemeChange(CursorTheme theme)
		{
			clear();
		}

		@Override
		public void onShutdown()
		{
			clear();
		}
	};

	@Nullable
	public BufferedImage getImage(Sprite sprite)
	{
		try
		{
			return spriteCache.get(sprite);
		}
		catch (ExecutionException e)
		{
			return null;
		}
	}

	public void clear()
	{
		spriteCache.invalidateAll();
	}

	public boolean canOverrideDefaultCursor()
	{
		return !isCustomCursorPluginEnabled && isCustomDefaultCursorEnabled;
	}

	public boolean canDefaultCursorOverrideWithOverlay()
	{
		return canOverrideDefaultCursor() && isDefaultCursorOverlayEnabled && !isLoggedOut && isCursorInBounds;
	}
}

package com.github.ldavid432.contextualcursor;

import static com.github.ldavid432.contextualcursor.ContextualCursorConfig.GROUP;
import com.github.ldavid432.contextualcursor.config.CursorBackgroundMode;
import com.github.ldavid432.contextualcursor.config.CursorSource;
import com.github.ldavid432.contextualcursor.config.CursorTheme;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(GROUP)
public interface ContextualCursorConfig extends Config
{
	String GROUP = "contextualcursor";
	String DEBUG_TOOLTIP = "showDebugTooltip";
	String SCALE = "scale";
	String ITEM_SCALE = "itemScale";
	String SCALE_SMOOTHING = "scaleSmoothing";
	String ITEM_SCALE_SMOOTHING = "itemSmoothScaling";
	String CURSOR_THEME = "cursorTheme";
	String CUSTOM_CURSOR = "customCursor";
	String DEFAULT_CURSOR_OVERLAY = "genericCursorOverlay";
	String USE_ITEM_CURSOR = "useItem";
	String PERSIST_ITEMS = "persistItems";
	String PERSIST_SPELLS = "persistSpells";
	String HIDE_CURSOR_BACKGROUND = "hideCursorBackground";
	String CURSOR_BACKGROUND_MODE = "cursorBackgroundMode";
	String LAST_UPDATE_SEEN = "lastUpdateSeen";

	@ConfigSection(
		name = "Theme",
		description = "Modify the cursor theme",
		position = 0
	)
	String themeSection = "themeSection";

	@ConfigItem(
		keyName = CURSOR_THEME,
		name = "Cursor Theme",
		description = "Theme for the contextual cursor background and default cursor<br>" +
			"OldSchool: Custom-made theme to match the osrs UI<br>" +
			"RuneScape 2: Sprites taken directly from RS2",
		position = 0,
		section = themeSection
	)
	default CursorTheme getCursorTheme()
	{
		return CursorTheme.RS2;
	}

	@ConfigItem(
		keyName = CURSOR_BACKGROUND_MODE,
		name = "Background",
		description = "Set when to show the contextual background frame<br>" +
			"Never: Always keep the default cursor shown, contextual sprites will float next to it<br>" +
			"For contextual actions: Show the background behinds contextual sprites only (same as RS2)<br>" +
			"For any action: Show the background on all <strong>non-ignored</strong> actions, even non-contextual actions<br>" +
			"Previously, 'For any action' was the default",
		position = 1,
		section = themeSection
	)
	default CursorBackgroundMode getCursorBackgroundMode()
	{
		return CursorBackgroundMode.FOR_CONTEXTUAL;
	}

	@ConfigItem(
		keyName = "hideKeybind",
		name = "Hide Cursor Keybind",
		description = "When held this button will disable the contextual cursor. Default is ALT<br>" +
			"Note: This will not disable the default cursor override",
		position = 2,
		// TODO: Maybe expose this eventually - isn't really useful atm, especially when the key remapping plugin consumes most single characters
		hidden = true
	)
	default Keybind getHideKeybind()
	{
		return Keybind.ALT;
	}

	@ConfigItem(
		keyName = "cursorSource",
		name = "",
		description = "",
		position = 3,
		hidden = true
	)
	default CursorSource getCursorSource()
	{
		return CursorSource.LOCAL_JSON;
	}

	@ConfigSection(
		name = "Default cursor",
		description = "Adjust the default (non-contextual) cursor",
		position = 15
	)
	String defaultCursorSection = "defaultCursorSection";

	@ConfigItem(
		name = "Override default cursor",
		description = "Requires: Custom Cursor plugin OFF<br>" +
			"Override the default cursor with one that matches your cursor theme",
		keyName = CUSTOM_CURSOR,
		position = 0,
		section = defaultCursorSection
	)
	default boolean isCustomDefaultCursorEnabled()
	{
		return false;
	}

	@ConfigItem(
		name = "Use overlay for default cursor",
		description = "Requires: \"Override default cursor\" ON<br>" +
			"Uses an overlay for the default cursor instead of a real cursor<br>" +
			"This fixes Java's whitening of the default cursor as well as allows the default cursor to scale larger<br>" +
			"This does however make the cursor slightly slower than normal mouse movement. Should not be noticeable though.",
		keyName = DEFAULT_CURSOR_OVERLAY,
		position = 1,
		section = defaultCursorSection
	)
	default boolean isDefaultCursorOverlayEnabled()
	{
		return true;
	}

	@ConfigSection(
		name = "Scale",
		description = "Adjust the cursor scaling",
		position = 25
	)
	String scaleSection = "scaleSection";

	@Range(min = 5)
	@Units(Units.PERCENT)
	@ConfigItem(
		name = "Cursor Scale",
		description = "Scale the contextual cursors size",
		keyName = SCALE,
		position = 0,
		section = scaleSection
	)
	default int getCursorScale()
	{
		return 100;
	}

	@ConfigItem(
		name = "Smooth Cursor Scaling",
		description = "Use a smooth scaling algorithm to scale the cursor",
		keyName = SCALE_SMOOTHING,
		position = 1,
		section = scaleSection
	)
	default boolean isCursorSmoothScalingEnabled()
	{
		return false;
	}

	@Range(min = 20)
	@Units(Units.PERCENT)
	@ConfigItem(
		name = "Item Scale",
		description = "Scale items shown inside the contextual cursor",
		keyName = ITEM_SCALE,
		position = 2,
		section = scaleSection
	)
	default int getItemScale()
	{
		return 90;
	}

	@ConfigItem(
		name = "Smooth Item Scaling",
		description = "Use a smooth scaling algorithm to scale items shown inside the cursor",
		keyName = ITEM_SCALE_SMOOTHING,
		position = 3,
		section = scaleSection
	)
	default boolean isItemSmoothScalingEnabled()
	{
		return true;
	}

	@ConfigSection(
		name = "Miscellaneous",
		description = "Configure miscellaneous options",
		position = 40
	)
	String miscSection = "miscSection";

	@ConfigItem(
		name = "Use Item",
		description = "Show the item being used in the cursor",
		keyName = USE_ITEM_CURSOR,
		position = 0,
		section = miscSection
	)
	default boolean isShowUseItemCursorEnabled()
	{
		return true;
	}

	@ConfigItem(
		name = "Persist Items",
		description = "Keep showing the item cursor while an item is selected<br>" +
			"Requires: Use Item ON<br>" +
			"When disabled, items will only show in the cursor when hovering over a target",
		keyName = PERSIST_ITEMS,
		position = 1,
		section = miscSection
	)
	default boolean shouldPersistItems()
	{
		return true;
	}

	@ConfigItem(
		name = "Persist Spells",
		description = "Keep showing the spell cursor while a spell is selected<br>" +
			"When disabled, spells will only show in the cursor when hovering over a target",
		keyName = PERSIST_SPELLS,
		position = 2,
		section = miscSection
	)
	default boolean shouldPersistSpells()
	{
		return true;
	}

	@ConfigSection(
		name = "Ignores",
		description = "Don't show the contextual cursor for certain targets",
		position = 50
	)
	String ignoreSection = "ignoreSection";

	@ConfigItem(
		name = "Ignore NPCs",
		description = "Don't show contextual cursors on NPCs",
		keyName = "ignoreNpcs",
		position = 0,
		section = ignoreSection
	)
	default boolean shouldIgnoreNpcs()
	{
		return false;
	}

	@ConfigItem(
		name = "Ignore Objects",
		description = "Don't show contextual cursors on objects",
		keyName = "ignoreObjects",
		position = 1,
		section = ignoreSection
	)
	default boolean shouldIgnoreObjects()
	{
		return false;
	}

	@ConfigItem(
		name = "Ignore Inventory Items",
		description = "Don't show contextual cursors on items in your inventory",
		keyName = "ignoreItems",
		position = 2,
		section = ignoreSection
	)
	default boolean shouldIgnoreItems()
	{
		return false;
	}

	@ConfigItem(
		name = "Ignore Spells",
		description = "Don't show contextual cursors on spells",
		keyName = "ignoreSpells",
		position = 3,
		section = ignoreSection
	)
	default boolean shouldIgnoreSpells()
	{
		return false;
	}

	@ConfigItem(
		name = "Ignore Ground Items",
		description = "Don't show contextual cursors on items on the ground",
		keyName = "ignoreGroundItems",
		position = 4,
		section = ignoreSection
	)
	default boolean shouldIgnoreGroundItems()
	{
		return false;
	}

	@ConfigItem(
		name = "Ignore Players",
		description = "Don't show contextual cursors on players",
		keyName = "ignorePlayers",
		position = 5,
		section = ignoreSection
	)
	default boolean shouldIgnorePlayers()
	{
		return false;
	}

	@ConfigItem(
		name = "Ignore Interfaces",
		description = "Don't show contextual cursors on interfaces. It is not recommended to disable this as interface matching is not very accurate.",
		keyName = "ignoreInterfaces",
		position = 100,
		section = ignoreSection,
		// Maybe will look at adding this eventually but probably need to be more thorough with what is and isn't an interface
		//  Hopefully inventory and spellbook are good enough for now
		hidden = true
	)
	default boolean shouldIgnoreInterfaces()
	{
		return true;
	}

	@ConfigSection(
		name = "Debug",
		description = "Debugging options",
		position = 100,
		closedByDefault = true
	)
	String debugSection = "debugSection";

	@ConfigItem(
		name = "Debug Tooltip",
		description = "Shows a tooltip containing debug information on the current menu entry.<br>" +
			"If you'd like a specific menu entry to be added to the plugin you can screenshot<br>" +
			"the tooltip of your desired menu entry and include it in a GitHub issue.",
		keyName = DEBUG_TOOLTIP,
		position = 0,
		section = debugSection
	)
	default boolean isDebugTooltipEnabled()
	{
		return false;
	}

	int CURRENT_VERSION = 4;

	@ConfigItem(
		name = "Last seen version",
		description = "",
		keyName = LAST_UPDATE_SEEN,
		hidden = true
	)
	default int getLastSeenVersion()
	{
		return 0;
	}

}

package com.github.ldavid432.contextualcursor;

import static com.github.ldavid432.contextualcursor.ContextualCursorUtil.BLANK_MOUSE;
import com.github.ldavid432.contextualcursor.cursor.OffsetCursor;
import java.awt.Cursor;
import javax.annotation.Nullable;
import lombok.Value;
import net.runelite.client.ui.overlay.tooltip.Tooltip;

@Value(staticConstructor = "state")
public class ContextualCursorState
{
	// actual cursor
	@Nullable
	Cursor cursor;

	@Nullable
	OffsetCursor cursorBackground;

	// The offset here is technically the center
	@Nullable
	OffsetCursor cursorForeground;

	@Nullable
	Tooltip tooltip;

	public static ContextualCursorState genericCursor(Cursor cursor)
	{
		return state(cursor, null, null, null);
	}

	public static ContextualCursorState genericCursorOverlay(OffsetCursor cursor, Tooltip tooltip)
	{
		return state(BLANK_MOUSE, cursor, null, tooltip);
	}

	public static ContextualCursorState externalCursor(Cursor cursor)
	{
		return state(cursor, null, null, null);
	}

	public static ContextualCursorState clearCursor()
	{
		return genericCursor(null);
	}

	public static ContextualCursorState contextualCursor(OffsetCursor foreground, OffsetCursor background, Tooltip tooltip)
	{
		return state(BLANK_MOUSE, background, foreground, tooltip);
	}

	// Contextual cursor with background disabled and cursor overlay disabled
	public static ContextualCursorState contextualCursorHybrid(OffsetCursor foreground, Cursor cursor)
	{
		return state(cursor, null, foreground, null);
	}

	@Override
	public String toString()
	{
		return "ContextualCursorState{" +
			textOrEmpty("cursor=", cursor != null ? cursor.getName() : null) +
			textOrEmpty(", cursorBackground=", cursorBackground) +
			textOrEmpty(", cursorForeground=", cursorForeground) +
			textOrEmpty(", tooltip=", tooltip) +
			'}';
	}

	private String textOrEmpty(String prefix, Object value)
	{
		return value != null ? prefix + value : "";
	}
}

package com.github.ldavid432.contextualcursor;

import static com.github.ldavid432.contextualcursor.ContextualCursorConfig.CURSOR_BACKGROUND_MODE;
import static com.github.ldavid432.contextualcursor.ContextualCursorConfig.CUSTOM_CURSOR;
import static com.github.ldavid432.contextualcursor.ContextualCursorConfig.GROUP;
import static com.github.ldavid432.contextualcursor.ContextualCursorConfig.HIDE_CURSOR_BACKGROUND;
import static com.github.ldavid432.contextualcursor.ContextualCursorConfig.LAST_UPDATE_SEEN;
import com.github.ldavid432.contextualcursor.config.CursorBackgroundMode;
import com.github.ldavid432.contextualcursor.cursor.ContextualCursorDefinition;
import com.github.ldavid432.contextualcursor.cursor.Cursor;
import com.github.ldavid432.contextualcursor.cursor.ScaledPoint;
