	ENDS_WITH(String::endsWith),
	CONTAINS(String::contains),
	EQUALS(String::equals);

	@Delegate
	private final BiFunction<String, String, Boolean> predicate;
}

package com.github.ldavid432.contextualcursor.overlay;

import com.github.ldavid432.contextualcursor.ContextualCursorCache;
import com.github.ldavid432.contextualcursor.ContextualCursorState;
import static com.github.ldavid432.contextualcursor.ContextualCursorUtil.BLANK_CURSOR_NAME;
import static com.github.ldavid432.contextualcursor.ContextualCursorUtil.EMPTY_SCALED_POINT;
import static com.github.ldavid432.contextualcursor.ContextualCursorUtil.GENERIC_CURSOR_NAME;
import com.github.ldavid432.contextualcursor.cursor.OffsetCursor;
import com.github.ldavid432.contextualcursor.cursor.ScaledPoint;
import com.github.ldavid432.contextualcursor.sprite.Sprite;
import io.hydrox.contextualcursor.ContextualCursorPlugin;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.annotation.Nullable;
import javax.inject.Inject;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.ui.ClientUI;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * V2 render overlay
 */
@Slf4j
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ContextualCursorV2DrawOverlay extends Overlay
{
	private final Client client;
	private final ContextualCursorPlugin plugin;
	private final ClientUI clientUi;
	private final ContextualCursorCache cache;

	@Inject
	void init()
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(1f);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final ContextualCursorState nextState = plugin.getNextState();
		ContextualCursorState currentState = plugin.getCurrentState();

		if (nextState != null)
		{
			if (!nextState.equals(currentState))
			{
				log.debug("Changing state from \n  {} \n  to {}", currentState, nextState);
			}
			ContextualCursorState previousState = plugin.getPreviousState();
			boolean isCursorChange = ((previousState != null ? previousState.getCursor() : null) != nextState.getCursor()) ||
				// Another plugin has saved and restored our blank cursor, messing up our state. We need to restore it here
				(clientUi.getCurrentCursor().getName().equals(BLANK_CURSOR_NAME) && nextState.getCursor() != null &&
					!nextState.getCursor().getName().equals(BLANK_CURSOR_NAME) && nextState.getCursor().getName().equals(GENERIC_CURSOR_NAME));

			plugin.setPreviousState(currentState);
			currentState = nextState;
			plugin.setCurrentState(nextState);

			if (isCursorChange)
			{
				log.debug("Changing cursor from {} to {}",
					((previousState != null && previousState.getCursor() != null) ? previousState.getCursor().getName() : null),
					(nextState.getCursor() != null ? nextState.getCursor().getName() : null)
				);
				onCursorChange(currentState.getCursor());
			}
		}

		if (currentState != null && graphics != null)
		{
			onRender(currentState, graphics);
		}

		return null;
	}

	private void onCursorChange(Cursor newCursor)
	{
		if (newCursor == null)
		{
			clientUi.resetCursor();
		}
		else
		{
			clientUi.setCursor(newCursor);
		}
	}

	private void onRender(ContextualCursorState currentState, Graphics2D graphics)
	{
		final Point mousePos = client.getMouseCanvasPosition();

		OffsetCursor background = currentState.getCursorBackground();
		if (background != null)
		{
			BufferedImage backgroundImage = spriteImageOrNull(currentState.getCursorBackground().getSprite());
			if (backgroundImage != null)
			{
				graphics.drawImage(backgroundImage, mousePos.getX() + background.getOffset().getX(), mousePos.getY() + background.getOffset().getY(), null);
			}
		}

		OffsetCursor foreground = currentState.getCursorForeground();
		if (foreground != null)
		{
			BufferedImage foregroundImage = spriteImageOrNull(foreground.getSprite());
			if (foregroundImage != null)
			{
				ScaledPoint backgroundOffset = background != null ? background.getOffset() : EMPTY_SCALED_POINT;
				final int spriteX = backgroundOffset.getX() + foreground.getOffset().getX() - foregroundImage.getWidth(null) / 2;
				final int spriteY = backgroundOffset.getY() + foreground.getOffset().getY() - foregroundImage.getHeight(null) / 2;
				graphics.drawImage(foregroundImage, mousePos.getX() + spriteX, mousePos.getY() + spriteY, null);
			}
		}
	}

	@Nullable
	private BufferedImage spriteImageOrNull(Sprite sprite)
	{
		return sprite != null ? cache.getImage(sprite) : null;
	}

}

package com.github.ldavid432.contextualcursor.overlay;

import com.github.ldavid432.contextualcursor.ContextualCursorCache;
import com.github.ldavid432.contextualcursor.ContextualCursorState;
import io.hydrox.contextualcursor.ContextualCursorPlugin;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Objects;
import java.util.stream.Stream;
import javax.inject.Inject;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;

/**
 * V2 worker overlay - this must be separate in order for the tooltips to be rendered correctly in front of the mouse tooltips plugin
 */
@Slf4j
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ContextualCursorV2WorkerOverlay extends Overlay
{
	private final StateProvider stateProvider;
	private final ContextualCursorPlugin plugin;
	private final TooltipManager tooltipManager;
	private final MenuEntryProvider menuEntryProvider;
	private final ContextualCursorCache cache;

	@Inject
	void init()
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		// run before draw overlay
		setPriority(1.1f);
		// Also allow on world map and welcome screen
		drawAfterInterface(InterfaceID.TOPLEVEL_DISPLAY);
		menuEntryProvider.setListener(((menuEntry, isIgnored) -> {
			debugTooltip(isIgnored, menuEntry);
			return null;
		}));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		ContextualCursorState nextState = stateProvider.getState();

		plugin.setNextState(nextState);

		// Tooltips must be rendered in OverlayLayer.ABOVE_WIDGETS in order to be before the mouse tooltips plugin
		//  while graphics need to be ALWAYS_ON_TOP to be above the right click menu
		if (nextState != null && nextState.getTooltip() != null)
		{
			tooltipManager.addFront(nextState.getTooltip());
		}

		return null;
	}

	private void debugTooltip(boolean isIgnored, MenuEntry entry)
	{
		if (entry == null || !cache.isDebugTooltipEnabled())
		{
			return;
		}

		String ignored = null;
		if (isIgnored)
		{
			ignored = ColorUtil.wrapWithColorTag("Ignored", Color.RED);
		}

		String name = String.format("option=%s, type=%s", entry.getOption(), entry.getType());
		if (entry.getTarget() != null && !entry.getTarget().isBlank())
		{
			name += String.format(", target=%s", entry.getTarget());
		}

		String item = null;
		if (entry.isItemOp() || entry.getItemId() > 0)
		{
			item = String.format("Item: isItemOp=%s, id=%s", entry.isItemOp(), entry.getItemId());
		}

		String npc = null;
		if (entry.getNpc() != null)
		{
			npc = String.format("NPC: %s", entry.getNpc().getName());
		}

		String player = null;
		if (entry.getPlayer() != null)
		{
			player = String.format("Player: %s", entry.getPlayer().getName());
		}

		tooltipManager.addFront(
			new Tooltip(
				Stream.of("Contextual Cursor Debug:", ignored, name, item, npc, player)
					.filter(Objects::nonNull)
					.reduce((s1, s2) -> s1 + "<br>" + s2)
					.orElse("Contextual Cursor Debug:<br>" + name)
			)
		);
	}
}

package com.github.ldavid432.contextualcursor.overlay;

import com.github.ldavid432.contextualcursor.cursor.Cursor;
import com.github.ldavid432.contextualcursor.cursor.CursorProvider;
import static com.github.ldavid432.contextualcursor.menuentry.MenuEntryMatchers.hasOption;
import com.github.ldavid432.contextualcursor.sprite.Sprite;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.AllArgsConstructor;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;

/**
 * Provides sprites for item interactions. Primarily the function of this class is to get triggered before SelectedWidgetProvider.
 * Prioritizes custom item interactions, if none apply returns the use interaction (if enabled).
 */
@Singleton
@AllArgsConstructor(onConstructor_ = @Inject)
public class ItemProvider
{
	private final Client client;
	private final CursorProvider cursorProvider;

	@Nullable
	public Sprite getItemSprite(@Nullable MenuEntry menuEntry)
	{
		if (menuEntry == null || !hasOption("use").matches(menuEntry) || getItemId(menuEntry) < 0)
		{
			return null;
		}

		for (Cursor cursor : cursorProvider.getItemCursors())
		{
			if (cursor.getMatcher().matches(menuEntry))
			{
				return cursor.getSprite();
			}
		}

		return null;
	}

	private int getItemId(MenuEntry menuEntry)
	{
		if (menuEntry != null && menuEntry.getItemId() >= 0)
		{
			return menuEntry.getItemId();
		}
		else if (client.isWidgetSelected() && client.getSelectedWidget() != null && client.getSelectedWidget().getItemId() >= 0)
		{
			return client.getSelectedWidget().getItemId();
		}
		else
		{
			return -1;
		}
	}
}

package com.github.ldavid432.contextualcursor.overlay;

import static com.github.ldavid432.contextualcursor.ContextualCursorUtil.MENU_EXTRA_TOP;
import static com.github.ldavid432.contextualcursor.ContextualCursorUtil.MENU_OPTION_HEIGHT;
import com.github.ldavid432.contextualcursor.menuentry.MenuTarget;
import io.hydrox.contextualcursor.ContextualCursorPlugin;
import java.util.function.BiFunction;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuEntry;

@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class MenuEntryProvider
{
	private final Client client;
	private final ContextualCursorPlugin plugin;

	@Getter
	private MenuEntry lastSubmenuEntry = null;
	@Getter
	private boolean isInSubmenu = false;

	@Setter
	@Nullable
	private BiFunction<MenuEntry, Boolean, Void> listener = null;

	public MenuEntry getMenuEntry()
	{
		final MenuEntry menuEntry;

		if (client.isMenuOpen())
		{
			menuEntry = processMenu(client.getMenu());
		}
		else
		{
			isInSubmenu = false;
			lastSubmenuEntry = null;
			final MenuEntry[] menuEntries = client.getMenu().getMenuEntries();
			int last = menuEntries.length - 1;

			if (last < 0)
			{
				return null;
			}

			menuEntry = menuEntries[last];
		}

		if (menuEntry != null && !isEntryIgnored(menuEntry, isInSubmenu))
		{
			if (listener != null)
			{
				listener.apply(menuEntry, false);
			}
			return menuEntry;
		}
		else
		{
			if (listener != null)
			{
				listener.apply(menuEntry, true);
			}
			return null;
		}
	}

	private MenuEntry processMenu(Menu menu)
	{
		final MenuEntry lastSubmenuEntry1 = lastSubmenuEntry;
		// This is slightly bugged since there is a small margin around menus where they will stay open (see other comment below)
		//  so this may think you are in a submenu if you move just outside the parent menu where the submenu would appear
		//  Not much we can do about it unless there is a way to determine if a submenu is open or closed
		if (isCursorOutsideMenu(menu) && lastSubmenuEntry1 != null && lastSubmenuEntry1.getSubMenu() != null && !isCursorOutsideMenu(lastSubmenuEntry1.getSubMenu()))
		{
			return processSubmenu(lastSubmenuEntry1.getSubMenu());
		}
		// Outside of parent menu, not in a submenu
		else if (isCursorOutsideMenu(menu))
		{
			return null;
		}

		final MenuEntry hoveredMenuEntry = getHoveredMenuEntry(menu);
		if (hoveredMenuEntry == null)
		{
			return null;
		}

		// This can bug out on stuff with submenus too close together (looking at you forestry basket)
		//  since there is some logic to allow you to move over other entries and to the submenu without closing the submenu
		//  https://github.com/runelite/runelite/issues/19670#issuecomment-3621605835
		if (hoveredMenuEntry.getSubMenu() != null)
		{
			lastSubmenuEntry = hoveredMenuEntry;
		}

		isInSubmenu = false;

		return hoveredMenuEntry;
	}

	private MenuEntry processSubmenu(Menu submenu)
	{
		final MenuEntry hoveredMenuEntry = getHoveredMenuEntry(submenu);
		if (hoveredMenuEntry == null)
		{
			return null;
		}

		isInSubmenu = true;

		return hoveredMenuEntry;
	}

	private MenuEntry getHoveredMenuEntry(Menu menu)
	{
		final MenuEntry[] menuEntries = menu.getMenuEntries();

		final int fromTop = (client.getMouseCanvasPosition().getY() - MENU_EXTRA_TOP) - menu.getMenuY();

		final int index = menuEntries.length - (fromTop / MENU_OPTION_HEIGHT);

		if (index >= menuEntries.length || index < 0)
		{
			return null;
		}

		return menuEntries[index];
	}

	private boolean isCursorOutsideMenu(Menu menu)
	{
		return menu.getMenuX() > client.getMouseCanvasPosition().getX() || menu.getMenuX() + menu.getMenuWidth() < client.getMouseCanvasPosition().getX();
	}

	private boolean isEntryIgnored(MenuEntry entry, boolean isInSubmenu)
	{
		MenuTarget target = mapTarget(entry, isInSubmenu);
		return plugin.getIgnoredTargets().getOrDefault(target, false);
	}

	private MenuTarget mapTarget(MenuEntry entry, boolean isInSubmenu)
	{
		for (MenuTarget target : MenuTarget.VALUES)
		{
			if (target.getMatcher().matches(entry) ||
				// isInSubmenu isn't available in the MenuEntryMatcher
				(target == MenuTarget.ITEM && isInSubmenu && entry.getItemId() > 0))
			{
				return target;
			}
		}
		return MenuTarget.OTHER;
	}

}

package com.github.ldavid432.contextualcursor.overlay;

import com.github.ldavid432.contextualcursor.ContextualCursorCache;
import com.github.ldavid432.contextualcursor.sprite.ItemSprite;
import com.github.ldavid432.contextualcursor.sprite.Sprite;
import io.hydrox.contextualcursor.SpellSprite;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class SelectedWidgetProvider
{
	private final Client client;
	private final ContextualCursorCache cache;

	private Sprite persistedSprite = null;

	@Nullable
	public Sprite getSelectedSprite()
	{
		if (client.isWidgetSelected())
		{
			processSelected();
		}
		else if (persistedSprite != null)
		{
			persistedSprite = null;
		}
		return persistedSprite;
	}

	private void processSelected()
	{
		if (persistedSprite == null)
		{
			Widget selectedWidget = client.getSelectedWidget();
			if (selectedWidget == null)
			{
				persistedSprite = null;
				return;
			}

			if (cache.isShowUseItemCursorEnabled() && cache.isPersistItems() && selectedWidget.getItemId() > 0)
			{
				log.debug("Persisting item {}", selectedWidget.getItemId());
				persistedSprite = new ItemSprite(selectedWidget.getItemId());
			}
			else if (cache.isPersistSpells() &&
				selectedWidget.getParent() != null &&
				selectedWidget.getParent().getId() == InterfaceID.MagicSpellbook.SPELLLAYER)
			{
				for (SpellSprite spell : SpellSprite.values())
				{
					if (spell.getInterfaceID() == selectedWidget.getId())
					{
						log.debug("Persisting spell");
						persistedSprite = spell.getSprite();
						break;
					}
				}
			}
		}
	}
}

package com.github.ldavid432.contextualcursor.overlay;

import static com.github.ldavid432.contextualcursor.menuentry.MenuEntryMatchers.hasOption;
import com.github.ldavid432.contextualcursor.sprite.Sprite;
import io.hydrox.contextualcursor.SpellSprite;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.AllArgsConstructor;
import net.runelite.api.MenuEntry;
import net.runelite.client.util.Text;

@Singleton
@AllArgsConstructor(onConstructor_ = @Inject)
public class SpellProvider
{
	private static final Pattern SPELL_FINDER = Pattern.compile(">(.*?)(?:</col>| -> )");

	@Nullable
	public Sprite getSpellSprite(@Nullable MenuEntry menuEntry)
	{
		if (menuEntry == null || !hasOption("cast", "resurrect", "reanimate").matches(menuEntry))
		{
			return null;
		}

		final Matcher spellFinder = SPELL_FINDER.matcher(menuEntry.getTarget().toLowerCase());

		if (!spellFinder.find())
		{
			return null;
		}

		final String spellText = spellFinder.group(1);
		final SpellSprite spell = SpellSprite.get(Text.sanitize(spellText));
		if (spell == null)
		{
			return null;
		}

		return spell.getSprite();
	}
}

package com.github.ldavid432.contextualcursor.overlay;

import com.github.ldavid432.contextualcursor.ContextualCursorCache;
import com.github.ldavid432.contextualcursor.config.CursorBackgroundMode;
import com.github.ldavid432.contextualcursor.cursor.CursorProvider;
import com.github.ldavid432.contextualcursor.sprite.Sprite;
