				matcher = context.deserialize(object, NotMatcher.class);
				break;
			case "composite":
				matcher = context.deserialize(object, CompositeMatcher.class);
				break;
			case "string":
				matcher = context.deserialize(object, SimpleStringMatcher.class);
				break;
		}

